      "content": "import { describe, expect, test } from 'bun:test';
import { DomainError, type UseCaseContext } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { CreateTask } from '../application/create-task';
import { TaskCreated } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

describe('create_task use-case', () => {
  test(covers(['usecase:create_task', 'criterion:0001/persistencia-criacao'], 'salva, publica TaskCreated, retorna pending e rejeita id duplicado'), async () => {
    const tasks = new InMemoryTaskRepository();
    const useCase = new CreateTask(tasks);
    const published: TaskCreated[] = [];
    const ctx: UseCaseContext = {
      correlationId: 'corr-1',
      causationId: 'caus-1',
      async publish(events) { for (const event of events) if (event instanceof TaskCreated) published.push(event); },
    };

    const first = await useCase.execute({ task_id: 't1', title: '  Estudar DDD  ' }, ctx);

    expect(first).toEqual({ task_id: 't1', title: 'Estudar DDD', status: 'pending' });
    expect((await tasks.findById('t1'))?.id).toBe('t1');
    expect(published).toHaveLength(1);
    expect(published[0]?.payload).toEqual({ taskId: 't1', title: 'Estudar DDD' });

    let error: unknown;
    try {
      await useCase.execute({ task_id: 't1', title: 'Outra tarefa' }, ctx);
    } catch (caught) {
      error = caught;
    }

    expect(error).toBeInstanceOf(DomainError);
    expect((error as DomainError).code).toBe('TASK_ALREADY_EXISTS');
    expect(published).toHaveLength(1);
  });
});
